/**
 * Code-node port of the AI Automation ROI, Pricing & Retainer Calculator formulas.
 * Estimates only. Same arithmetic as the free spreadsheet's Calculator tab.
 */
'use strict';

function asNumber(value, fallback) {
  if (value == null || value === '') return fallback;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const n = parseFloat(String(value).replace(/,/g, '').replace(/%/g, ''));
  return Number.isFinite(n) ? n : fallback;
}

function roundUpTo(value, multiple) {
  if (value <= 0) return 0;
  return Math.ceil(value / multiple) * multiple;
}

function money(n) {
  const v = Math.round(n * 100) / 100;
  const sign = v < 0 ? '-' : '';
  const abs = Math.abs(v);
  const [int, frac] = abs.toFixed(2).split('.');
  const withCommas = int.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}$${withCommas}.${frac}`;
}

function monthsLabel(n) {
  if (n == null || n === 'n/a') return 'n/a';
  const v = Math.round(n * 100) / 100;
  return `${v} month${v === 1 ? '' : 's'}`;
}

/**
 * cfg: operator rates from the Config node.
 * src: client inputs from the form (or a flat test object).
 */
function estimate(src, cfg) {
  const name = String(src.name ?? src['Your name'] ?? '').trim();
  const email = String(src.email ?? src.Email ?? '').trim().toLowerCase();
  const company = String(src.company ?? src.Company ?? '').trim();
  const process = String(src.process ?? src['Process to automate'] ?? '').trim();

  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error(`Invalid or missing "email": ${JSON.stringify({ name, email })}`);
  }

  const tasksPerWeek = asNumber(src.tasksPerWeek ?? src['Tasks per week'], NaN);
  const minutesToday = asNumber(src.minutesToday ?? src['Minutes per task today'], NaN);
  const minutesAfter = asNumber(src.minutesAfter ?? src['Minutes still spent per task after automation'], NaN);
  const hourlyCost = asNumber(src.hourlyCost ?? src['Hourly cost of the person doing it now'], NaN);
  const otherMonthlySavings = asNumber(src.otherMonthlySavings ?? src['Other monthly savings (optional)'], 0);

  if (!Number.isFinite(tasksPerWeek) || tasksPerWeek < 0) {
    throw new Error('Tasks per week must be a number 0 or greater.');
  }
  if (!Number.isFinite(minutesToday) || minutesToday < 0) {
    throw new Error('Minutes per task today must be a number 0 or greater.');
  }
  if (!Number.isFinite(minutesAfter) || minutesAfter < 0) {
    throw new Error('Minutes still spent per task after automation must be a number 0 or greater.');
  }
  if (!Number.isFinite(hourlyCost) || hourlyCost < 0) {
    throw new Error('Hourly cost of the person doing it now must be a number 0 or greater.');
  }

  const workingWeeksPerYear = asNumber(cfg.workingWeeksPerYear, 48);
  const buildHours = asNumber(cfg.buildHours, 16);
  const hourlyRate = asNumber(cfg.hourlyRate, 75);
  const riskBuffer = asNumber(cfg.riskBuffer, 0.25);
  const toolCosts = asNumber(cfg.toolCosts, 40);
  const targetPaybackMonths = asNumber(cfg.targetPaybackMonths, 3);
  const depositPct = asNumber(cfg.depositPct, 0.5);
  const retainerRate = asNumber(cfg.retainerRate, 75);
  const monthlyTools = asNumber(cfg.monthlyTools, 20);
  const firstYearTier = String(cfg.firstYearTier || 'Standard');

  const hoursSavedPerWeek = Math.max(0, tasksPerWeek * (minutesToday - minutesAfter) / 60);
  const hoursSavedPerMonth = hoursSavedPerWeek * workingWeeksPerYear / 12;
  const valuePerMonth = hoursSavedPerMonth * hourlyCost + otherMonthlySavings;
  const valuePerYear = valuePerMonth * 12;

  const costBasedPrice = buildHours * hourlyRate * (1 + riskBuffer) + toolCosts;
  const suggestedPilotPrice = roundUpTo(costBasedPrice, 50);
  const valueCeiling = valuePerMonth * targetPaybackMonths;
  const clientPayback = valuePerMonth > 0 ? suggestedPilotPrice / valuePerMonth : 'n/a';
  let paybackCheck;
  if (valuePerMonth <= 0) paybackCheck = "Enter the client's numbers above";
  else if (suggestedPilotPrice <= valueCeiling) paybackCheck = 'OK: within target payback';
  else paybackCheck = 'Over target payback: shrink the scope or confirm the value';
  const depositDue = suggestedPilotPrice * depositPct;
  const balanceDue = suggestedPilotPrice - depositDue;
  const effectiveHourly = buildHours > 0 ? (suggestedPilotPrice - toolCosts) / buildHours : 0;

  const tierDefs = [
    { name: 'Essentials', hours: asNumber(cfg.essentialsHours, 2), discount: asNumber(cfg.essentialsDiscount, 0), response: '2 business days' },
    { name: 'Standard', hours: asNumber(cfg.standardHours, 4), discount: asNumber(cfg.standardDiscount, 0.05), response: '1 business day' },
    { name: 'Growth', hours: asNumber(cfg.growthHours, 8), discount: asNumber(cfg.growthDiscount, 0.10), response: 'Same business day' },
  ];
  const tiers = tierDefs.map((t) => {
    const monthlyPrice = roundUpTo(t.hours * retainerRate * (1 - t.discount) + monthlyTools, 25);
    const shareOfValue = valuePerMonth > 0 ? monthlyPrice / valuePerMonth : 'n/a';
    const netMonthlyValue = valuePerMonth - monthlyPrice;
    let flag = '';
    if (valuePerMonth > 0) {
      flag = monthlyPrice > valuePerMonth * 0.5
        ? "Check: over half the client's monthly value"
        : 'OK';
    }
    return { ...t, monthlyPrice, shareOfValue, netMonthlyValue, flag };
  });

  const chosen = tiers.find((t) => t.name.toLowerCase() === firstYearTier.toLowerCase()) || tiers[1];
  const firstYearCost = suggestedPilotPrice + 11 * chosen.monthlyPrice;
  const valueOver11Months = valuePerMonth * 11;
  const returnMultiple = firstYearCost > 0 ? valueOver11Months / firstYearCost : 0;
  let firstYearCheck = '';
  if (firstYearCost > 0) {
    firstYearCheck = returnMultiple >= 1
      ? 'Estimated value exceeds year-one cost'
      : 'Estimated value is below year-one cost: rethink scope or tier';
  }

  const firstName = name.split(/\s+/)[0] || 'there';
  const companyBit = company ? ` for ${company}` : '';
  const processBit = process ? `Process you described: ${process}\n\n` : '';

  const tierLines = tiers.map((t) => {
    const share = t.shareOfValue === 'n/a' ? 'n/a' : `${Math.round(t.shareOfValue * 100)}% of monthly value`;
    return `${t.name}: ${money(t.monthlyPrice)} / month (${t.hours} hours, ${Math.round(t.discount * 100)}% off the hourly rate, ${t.response}). ${share}. ${t.flag}`.trim();
  }).join('\n');

  const disclaimer = 'These figures are estimates only. They depend entirely on the numbers entered and are not a forecast or guarantee of savings, revenue or income, and not a formal quote, proposal, or financial, tax or legal advice.';

  const emailBody =
    `Hi ${firstName},\n\n` +
    `Thanks for sharing the numbers${companyBit}. Here is an estimate based on what you entered, using a published cost based pricing model. ${disclaimer}\n\n` +
    processBit +
    `Client value (estimate)\n` +
    `Hours saved per week: ${Math.round(hoursSavedPerWeek * 100) / 100}\n` +
    `Hours saved per month: ${Math.round(hoursSavedPerMonth * 100) / 100}\n` +
    `Estimated value per month: ${money(valuePerMonth)}\n` +
    `Estimated value per year: ${money(valuePerYear)}\n\n` +
    `Suggested pilot\n` +
    `Cost based price: ${money(costBasedPrice)}\n` +
    `Suggested pilot price (rounded up to $50): ${money(suggestedPilotPrice)}\n` +
    `Value ceiling (${targetPaybackMonths} months of value): ${money(valueCeiling)}\n` +
    `Client payback on the pilot: ${monthsLabel(clientPayback)}\n` +
    `Check: ${paybackCheck}\n` +
    `Deposit to start (${Math.round(depositPct * 100)}%): ${money(depositDue)}\n` +
    `Balance due on acceptance: ${money(balanceDue)}\n\n` +
    `Monthly retainer options after handover\n` +
    `${tierLines}\n\n` +
    `First year view (${chosen.name} retainer)\n` +
    `Pilot plus 11 months of retainer: ${money(firstYearCost)}\n` +
    `Estimated value over those 11 months: ${money(valueOver11Months)}\n` +
    `Estimated return (value ÷ cost): ${Math.round(returnMultiple * 100) / 100}x\n` +
    `Check: ${firstYearCheck}\n\n` +
    (cfg.signature || 'Best,\nYour Name\nYour Company');

  const completionTitle = paybackCheck.startsWith('OK')
    ? 'Your estimate is ready'
    : 'Your estimate is ready (please read the payback check)';
  const completionMessage =
    `Estimated value per month: ${money(valuePerMonth)}\n` +
    `Suggested pilot price: ${money(suggestedPilotPrice)}\n` +
    `Payback: ${monthsLabel(clientPayback)}\n` +
    `Check: ${paybackCheck}\n\n` +
    `We will also email a copy to ${email}. ${disclaimer}`;

  const subjectPrefix = cfg.subjectPrefix || 'Your automation estimate';
  const subject = company ? `${subjectPrefix} (${company})` : subjectPrefix;

  return {
    name,
    firstName,
    email,
    company,
    process,
    tasksPerWeek,
    minutesToday,
    minutesAfter,
    hourlyCost,
    otherMonthlySavings,
    hoursSavedPerWeek,
    hoursSavedPerMonth,
    valuePerMonth,
    valuePerYear,
    costBasedPrice,
    suggestedPilotPrice,
    valueCeiling,
    clientPayback,
    paybackCheck,
    depositDue,
    balanceDue,
    effectiveHourly,
    tiers,
    firstYearTier: chosen.name,
    firstYearCost,
    valueOver11Months,
    returnMultiple,
    firstYearCheck,
    subject,
    emailBody,
    completionTitle,
    completionMessage,
    receivedAt: new Date().toISOString(),
  };
}

const cfg = $('Config').first().json;
const out = [];
for (const item of $input.all()) {
  const src = item.json.body ?? item.json;
  out.push({ json: estimate(src, cfg) });
}
return out;
